1	// Operaciones sobre la instancia de Moodle: desplegar/retirar plugins generados, verificar que el core
2	// quedó intacto, resetear estado y validar sintaxis PHP. Todo determinista, sin IA.
3	import fs from 'node:fs';
4	import path from 'node:path';
5	import { RAIZ, MOODLE_SRC, DC, sh, archivos } from './util.mjs';
6	
7	const php = (args) => sh(`${DC} exec -T -u www-data web php ${args}`, { timeout: 10 * 60_000 });
8	
9	/** Plugins presentes en salidas/<spec>/codigo: directorios con version.php. Devuelve [{componente, rel}] */
10	export function pluginsDe(specDir) {
11	  const base = `${specDir}/codigo`;
12	  return archivos(base, (f) => f.endsWith('/version.php')).map((f) => {
13	    const rel = path.relative(base, path.dirname(f)); // p. ej. public/mod/quiz/accessrule/reconocimiento
14	    const src = fs.readFileSync(path.join(RAIZ, f), 'utf8');
15	    const m = src.match(/\$plugin->component\s*=\s*['"]([a-z0-9_]+)['"]/);
16	    return { componente: m ? m[1] : null, rel, versionFile: f };
17	  });
18	}
19	
20	export function lintPHP(specDir) {
21	  const fallos = [];
22	  for (const f of archivos(`${specDir}/codigo`, (x) => x.endsWith('.php'))) {
23	    // El contenedor web no monta la raíz del repo: se pasa el contenido por stdin (php -l lee stdin).
24	    const r = sh(`${DC} exec -T web php -l`, { input: fs.readFileSync(path.join(RAIZ, f), 'utf8') });
25	    if (r.code !== 0) fallos.push(`${f}: ${(r.out + r.err).trim()}`);
26	  }
27	  return fallos;
28	}
29	
30	/** Copia los plugins generados al árbol de Moodle y corre la actualización. */
31	export function desplegar(specDir) {
32	  const plugins = pluginsDe(specDir);
33	  for (const p of plugins) {
34	    const destino = path.join(MOODLE_SRC, p.rel);
35	    fs.rmSync(destino, { recursive: true, force: true });
36	    fs.cpSync(path.join(RAIZ, specDir, 'codigo', p.rel), destino, { recursive: true });
37	  }
38	  const up = php('admin/cli/upgrade.php --non-interactive --allow-unstable');
39	  const purge = php('admin/cli/purge_caches.php');
40	  return { plugins, ok: up.code === 0 && !/error|exception/i.test(up.out.slice(-2000)), salida: (up.out + up.err).slice(-6000), purge: purge.code === 0 };
41	}
42	
43	/** Desinstala y quita del árbol los plugins de un spec (para la prueba "sin la funcionalidad"). */
44	export function retirar(specDir) {
45	  const plugins = pluginsDe(specDir).filter((p) => p.componente);
46	  if (!plugins.length) return { ok: true, salida: 'sin plugins' };
47	  const r = php(`admin/cli/uninstall_plugins.php --plugins=${plugins.map((p) => p.componente).join(',')} --run`);
48	  for (const p of plugins) fs.rmSync(path.join(MOODLE_SRC, p.rel), { recursive: true, force: true });
49	  php('admin/cli/purge_caches.php');
50	  return { ok: r.code === 0, salida: (r.out + r.err).slice(-4000) };
51	}
52	
53	/**
54	 * El core de Moodle no se toca: en el árbol de Moodle solo pueden aparecer directorios NUEVOS que sean
55	 * plugins generados por la fábrica. Cualquier archivo modificado/borrado del core => violación.
56	 */
57	export function verificarCoreIntacto(rutasPermitidas) {
58	  const r = sh('git status --porcelain --untracked-files=normal', { cwd: MOODLE_SRC });
59	  const violaciones = [];
60	  for (const linea of r.out.split('\n').filter(Boolean)) {
61	    const estado = linea.slice(0, 2);
62	    const ruta = linea.slice(3).replace(/\/$/, '');
63	    if (ruta === 'vendor' || ruta.startsWith('vendor/')) continue; // Composer
64	    const permitido = estado === '??' && rutasPermitidas.some((p) => ruta === p || ruta.startsWith(p + '/') || p.startsWith(ruta + '/'));
65	    if (!permitido) violaciones.push(linea);
66	  }
67	  return violaciones;
68	}
69	
70	export function reset() {
71	  const a = sh(`${DC} exec -T -u www-data web php /opt/seed/reset.php`);
72	  // Tareas ad hoc en cola (p. ej. limpieza tras borrar actividades, migraciones de mod_qbank) se ejecutan ahora,
73	  // no a mitad de una prueba: el estado inicial de cada corrida es siempre el mismo.
74	  const t = sh(`${DC} exec -T -u www-data web php admin/cli/adhoc_task.php --execute`);
75	  const b = sh(`${DC} exec -T web curl -s -X POST http://receptor/_reset`);
76	  // reset.php purga cachés y cambia la revisión del tema: sin calentar, la primera carga en el navegador
77	  // se queda ~30 s en styles.php (bloquea domcontentloaded) y agota el timeout de page.goto.
78	  sh(`u=$(curl -s -m 60 http://localhost:8090/login/index.php | grep -oE 'http://[^"]*theme/styles\\.php/[^"]*' | head -1); [ -n "$u" ] && curl -s -o /dev/null -m 120 "$u"`);
79	  return { ok: a.code === 0 && b.code === 0, salida: a.out + a.err + b.out + (t.code ? t.err : '') };
80	}
81	
82	export function moodleArriba() {
83	  return sh('curl -s -o /dev/null -w "%{http_code}" http://localhost:8090/login/index.php').out === '200';
84	}
