 * @return bool true if successful, false if not
 */
public function add($setting) {
    if (!($setting instanceof \core_admin\setting)) {
        debugging('error - not a setting instance');
        return false;
    }

    $name = $setting->name;
    if ($setting->plugin) {
        $name = $setting->plugin . $name;
    }

    $this->settings->{$name} = $setting;
    return true;
}

